const item = $input.first();
const j = item.json || {};

return [
  {
    json: {
      sourceType: 'drive',
      sourceId: j.id || '',
      sender: j.lastModifyingUser?.emailAddress || j.owners?.[0]?.emailAddress || '',
      subject: j.name || '',
      body: '',
      receivedAt: j.createdTime || j.modifiedTime || '',
      fileName: j.name || j.originalFilename || '',
      mimeType: j.mimeType || '',
      fileUrl: j.webContentLink || j.webViewLink || '',
      attachmentBinaryKey: '',
      hasBinary: false,
      md5Checksum: j.md5Checksum || '',
      sha256Checksum: j.sha256Checksum || '',
      parentIds: j.parents || [],
      original: j,
    },
    binary: item.binary || {},
  },
];

const item = $input.first();
const j = item.json || {};
const binaryKeys = item.binary ? Object.keys(item.binary) : [];

const attachmentKey = binaryKeys[0] || '';
const attachment = attachmentKey ? item.binary[attachmentKey] : null;

return [
  {
    json: {
      sourceType: 'gmail',
      sourceId: j.messageId || j.id || '',
      sender: j.from?.text || j.from?.value?.[0]?.address || '',
      subject: j.subject || '',
      body: j.text || j.html || '',
      receivedAt: j.date || '',
      fileName: attachment?.fileName || j.subject || 'email',
      mimeType: attachment?.mimeType || '',
      fileUrl: '',
      attachmentBinaryKey: attachmentKey,
      hasBinary: binaryKeys.length > 0,
      labelIds: j.labelIds || [],
      threadId: j.threadId || '',
      original: j,
    },
    binary: item.binary || {},
  },
];

const item = $input.first();
const j = item.json || {};
const text = j.text || '';

const extract = (regex) => {
  const match = text.match(regex);
  return match ? match[1].trim() : null;
};

const upstream = $('Route by File Format').first().json;

return [
  {
    json: {
      sourceType: upstream.sourceType,
      sourceId: upstream.sourceId,
      sender: upstream.sender,
      subject: upstream.subject,
      fileName: upstream.fileName,
      mimeType: upstream.mimeType,
      fileUrl: upstream.fileUrl,
      attachmentBinaryKey: upstream.attachmentBinaryKey,
      original: upstream.original,
      text,
      regex: {
        invoiceNo: extract(/Invoice No:\s*([^\n]+)/),
        invoiceDate: extract(/Invoice Date:\s*([^\n]+)/),
        billedTo: extract(/BILLED TO\n([^\n]+)/),
        subtotal: extract(/Subtotal:\s*₹?([0-9,.]+)/),
        igst: extract(/IGST \(18%\):\s*₹?([0-9,.]+)/),
        grandTotal: extract(/Grand Total:\s*₹?([0-9,.]+)/),
        bankAccount: extract(/Account No:\s*([0-9]+)/),
        ifscCode: extract(/IFSC Code:\s*([A-Z0-9]+)/),
      },
    },
    binary: item.binary || {},
  },
];

const item = $input.first();
const j = item.json || {};
let raw = j.content?.parts?.[0]?.text || '';

raw = raw.trim();
if (raw.startsWith('```')) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  raw = raw.slice(start, end + 1);
}

let invoice;
try {
  invoice = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse LLM JSON: ' + e.message);
}

const upstream = $('Analyze PDF Text and Regex').first().json;
const regex = upstream.regex || {};

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

const conf = (val, fallback) => (val !== null && val !== undefined && val !== '' ? 0.95 : (fallback ?? 0.5));

return [
  {
    json: {
      vendor: {
        name: invoice.vendor_name ?? regex.billedTo ?? null,
        address: invoice.vendor_address ?? null,
        gstin_or_tax_id: invoice.vendor_gstin ?? null,
        pan: invoice.vendor_pan ?? null,
      },
      customer: {
        name: invoice.customer_name ?? regex.billedTo ?? null,
        address: invoice.customer_address ?? null,
        gstin_or_tax_id: invoice.customer_gstin ?? null,
        pan: invoice.customer_pan ?? null,
      },
      invoice: {
        invoice_number: invoice.invoice_number ?? regex.invoiceNo ?? null,
        invoice_date: invoice.invoice_date ?? regex.invoiceDate ?? null,
        due_date: invoice.due_date ?? null,
        po_number: invoice.po_number ?? null,
      },
      amounts: {
        subtotal: num(invoice.subtotal ?? regex.subtotal),
        tax_amount: num(invoice.igst ?? invoice.tax_amount ?? regex.igst),
        total: num(invoice.grand_total ?? invoice.total_amount ?? regex.grandTotal),
        currency: invoice.currency ?? 'INR',
      },
      bank: {
        bank_name: invoice.bank_name ?? null,
        account_name: invoice.account_name ?? null,
        account_number: invoice.account_number ?? regex.bankAccount ?? null,
        ifsc_code: invoice.ifsc_code ?? regex.ifscCode ?? null,
      },
      line_items: (invoice.line_items || []).map((li) => ({
        description: li.item_name ?? li.description ?? null,
        quantity: li.qty ?? li.quantity ?? null,
        unit: li.unit ?? null,
        unit_price: num(li.rate ?? li.unit_price),
        line_total: num(li.amount ?? li.line_total),
        description_confidence: 0.95,
      })),
      confidence: {
        invoice_number: conf(invoice.invoice_number ?? regex.invoiceNo),
        invoice_date: conf(invoice.invoice_date ?? regex.invoiceDate),
        due_date: conf(invoice.due_date),
        po_number: conf(invoice.po_number),
        vendor_name: conf(invoice.vendor_name ?? regex.billedTo),
        total_amount: conf(invoice.grand_total ?? invoice.total_amount ?? regex.grandTotal),
      },
      sourceType: upstream.sourceType,
      sourceId: upstream.sourceId,
      fileName: upstream.fileName,
      mimeType: upstream.mimeType,
      fileUrl: upstream.fileUrl,
      original: upstream.original,
      extractionMethod: 'pdf_text_llm',
      vendor_name: invoice.vendor_name ?? regex.billedTo ?? null,
      invoice_number: invoice.invoice_number ?? regex.invoiceNo ?? null,
      txn_date: invoice.invoice_date ?? regex.invoiceDate ?? null,
      due_date: invoice.due_date ?? invoice.invoice_date ?? regex.invoiceDate ?? null,
      po_number: invoice.po_number ?? null,
      source_type: upstream.sourceType,
      source_id: upstream.sourceId,
      currency: invoice.currency ?? 'INR',
      total_amount: num(invoice.grand_total ?? invoice.total_amount ?? regex.grandTotal),
      quickbooks_vendor_id: '',
      quickbooks_expense_account_id: '',
      regexHints: regex,
      items_summary: (invoice.line_items || [])
        .map((i) => `${i.item_name ?? i.description ?? 'item'} (₹${i.amount ?? i.line_total ?? ''})`)
        .join(', '),
    },
  },
];

const item = $input.first();
const j = item.json || {};
let raw = j.content?.parts?.[0]?.text || '';

raw = raw.trim();
if (raw.startsWith('```')) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  raw = raw.slice(start, end + 1);
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse LLM JSON: ' + e.message);
}

const inv = parsed.invoice_details || {};
const vendor = parsed.vendor_details || {};
const customer = parsed.customer_details || {};
const totals = parsed.totals || {};
const bank = parsed.bank_details || {};
const lineItems = parsed.line_items || [];

const getVal = (obj, key) => obj[key]?.value ?? null;
const getConf = (obj, key) => obj[key]?.confidence ?? null;

const upstream = $('Route by File Format').first().json;

return [
  {
    json: {
      vendor: {
        name: getVal(vendor, 'name'),
        address: getVal(vendor, 'address'),
        gstin_or_tax_id: getVal(vendor, 'gstin'),
        pan: getVal(vendor, 'pan'),
      },
      customer: {
        name: getVal(customer, 'name'),
        address: getVal(customer, 'address'),
        gstin_or_tax_id: getVal(customer, 'gstin'),
        pan: getVal(customer, 'pan'),
      },
      invoice: {
        invoice_number: getVal(inv, 'invoice_number'),
        invoice_date: getVal(inv, 'invoice_date'),
        due_date: getVal(inv, 'due_date'),
        po_number: getVal(inv, 'purchase_order_number'),
      },
      amounts: {
        subtotal: getVal(totals, 'subtotal'),
        tax_amount: getVal(totals, 'tax_amount'),
        total: getVal(totals, 'total_amount'),
        currency: getVal(totals, 'currency'),
      },
      bank: {
        bank_name: getVal(bank, 'bank_name'),
        account_name: getVal(bank, 'account_name'),
        account_number: getVal(bank, 'account_number'),
        ifsc_code: getVal(bank, 'ifsc_code'),
      },
      line_items: lineItems.map((li) => ({
        description: li.description?.value ?? null,
        quantity: li.quantity?.value ?? null,
        unit: li.unit?.value ?? null,
        unit_price: li.rate?.value ?? null,
        line_total: li.amount?.value ?? null,
        description_confidence: li.description?.confidence ?? null,
      })),
      confidence: {
        invoice_number: getConf(inv, 'invoice_number'),
        invoice_date: getConf(inv, 'invoice_date'),
        due_date: getConf(inv, 'due_date'),
        po_number: getConf(inv, 'purchase_order_number'),
        vendor_name: getConf(vendor, 'name'),
        total_amount: getConf(totals, 'total_amount'),
      },
      sourceType: upstream.sourceType,
      sourceId: upstream.sourceId,
      fileName: upstream.fileName,
      mimeType: upstream.mimeType,
      fileUrl: upstream.fileUrl,
      original: upstream.original,
      extractionMethod: 'image_vision',
      vendor_name: getVal(vendor, 'name'),
      invoice_number: getVal(inv, 'invoice_number'),
      txn_date: getVal(inv, 'invoice_date'),
      due_date: getVal(inv, 'due_date') || getVal(inv, 'invoice_date'),
      po_number: getVal(inv, 'purchase_order_number'),
      source_type: upstream.sourceType,
      source_id: upstream.sourceId,
      currency: getVal(totals, 'currency') || 'INR',
      total_amount: getVal(totals, 'total_amount'),
      quickbooks_vendor_id: '',
      quickbooks_expense_account_id: '',
    },
  },
];

